      if (BN.kind === 'pill') return `<rect x="${bx}" y="${y}" width="${w}" height="20" rx="10" fill="#0f172a" fill-opacity=".85"/><text x="${alignR ? x - 9 : x + 9}" y="${y + 14}" text-anchor="${ax}" font-size="11.5" font-weight="800" fill="#fff">${txt}</text>`;
